import { totalCents, type Channel, type Order } from "./order.js";

export const ORDER_PLACED_TOPIC = "orders.placed";
export const ORDER_CANCELLED_TOPIC = "orders.cancelled";

/** Published when an order has been accepted and its payment authorized. */
export interface OrderPlaced {
  readonly type: "OrderPlaced";
  readonly schemaVersion: 3;
  readonly orderId: string;
  readonly customerId: string;
  /** Legacy field; a known ARCH-6 exception tracked in the PII baseline. */
  readonly customerEmail: string;
  /** ISO-8601 instant. */
  readonly createdAt: string;
  readonly channel: Channel;
  /** ISO-4217 code. */
  readonly currency: string;
  /** Integer, minor units. */
  readonly amountCents: number;
  readonly lines: ReadonlyArray<{
    readonly sku: string;
    readonly qty: number;
    readonly unitPriceCents: number;
  }>;
}

/** Published when a placed order is cancelled. */
export interface OrderCancelled {
  readonly type: "OrderCancelled";
  readonly schemaVersion: 1;
  readonly orderId: string;
  readonly customerId: string;
  /** ISO-8601 instant. */
  readonly cancelledAt: string;
  readonly reason?: string;
}

export type DomainEvent = OrderPlaced | OrderCancelled;

/** The single place where an `OrderPlaced` event is built. */
export function orderPlaced(order: Order): OrderPlaced {
  return {
    type: "OrderPlaced",
    schemaVersion: 3,
    orderId: order.id,
    customerId: order.customerId,
    customerEmail: order.customerEmail,
    createdAt: order.placedAt,
    channel: order.channel,
    currency: order.currency,
    amountCents: totalCents(order),
    lines: order.lines.map((line) => ({
      sku: line.sku,
      qty: line.qty,
      unitPriceCents: line.unitPriceCents,
    })),
  };
}

/** The single place where an `OrderCancelled` event is built. */
export function orderCancelled(order: Order, cancelledAt: string, reason?: string): OrderCancelled {
  return {
    type: "OrderCancelled",
    schemaVersion: 1,
    orderId: order.id,
    customerId: order.customerId,
    cancelledAt,
    ...(reason === undefined ? {} : { reason }),
  };
}

export function topicFor(event: DomainEvent): string {
  switch (event.type) {
    case "OrderPlaced":
      return ORDER_PLACED_TOPIC;
    case "OrderCancelled":
      return ORDER_CANCELLED_TOPIC;
  }
}

/** Partition key: all events of one order are ordered relative to each other. */
export function partitionKeyFor(event: DomainEvent): string {
  return event.orderId;
}

import { asObject, FieldReader } from "./fieldReader.js";

export const CHANNELS = ["web", "store", "marketplace"] as const;
export type Channel = (typeof CHANNELS)[number];

/** The part of `OrderPlaced` that analytics-ingest relies on. Other fields are ignored. */
export interface OrderPlacedEvent {
  readonly orderId: string;
  readonly createdAt: Date;
  readonly channel: Channel;
  readonly currency: string;
  readonly lines: ReadonlyArray<{ readonly sku: string; readonly qty: number }>;
}

/** The part of `OrderCancelled` that analytics-ingest relies on. */
export interface OrderCancelledEvent {
  readonly orderId: string;
  readonly cancelledAt: Date;
}

/**
 * Validates an untrusted `OrderPlaced` event. Every problem is collected;
 * any problem throws `ContractViolationError` (missing or unknown `channel`, unparseable `createdAt`, ...).
 */
export function decodeOrderPlaced(raw: unknown): OrderPlacedEvent {
  const event = asObject("OrderPlaced", raw);
  const reader = new FieldReader(event);

  if (event.type !== "OrderPlaced") {
    reader.issues.push(`type: expected "OrderPlaced", got ${JSON.stringify(event.type)}`);
  }
  const orderId = reader.string("orderId");
  const createdAt = reader.isoInstant("createdAt");
  const channel = reader.oneOf("channel", CHANNELS);
  const currency = reader.currency("currency");

  const lines = reader.array("lines").map((rawLine, index) => {
    const line = reader.child(`lines[${index}]`, rawLine);
    const decoded = { sku: line.string("sku"), qty: line.positiveInteger("qty") };
    reader.adopt(line);
    return decoded;
  });

  reader.assertValid("OrderPlaced");
  return { orderId, createdAt, channel, currency, lines };
}

export function decodeOrderCancelled(raw: unknown): OrderCancelledEvent {
  const event = asObject("OrderCancelled", raw);
  const reader = new FieldReader(event);

  if (event.type !== "OrderCancelled") {
    reader.issues.push(`type: expected "OrderCancelled", got ${JSON.stringify(event.type)}`);
  }
  const orderId = reader.string("orderId");
  const cancelledAt = reader.isoInstant("cancelledAt");

  reader.assertValid("OrderCancelled");
  return { orderId, cancelledAt };
}

import { ContractViolationError } from "./errors.js";
import { isCurrencyCode, isMinorUnits } from "./money.js";

/** The part of `OrderPlaced` that billing-service relies on. Other fields are ignored. */
export interface OrderPlacedEvent {
  readonly orderId: string;
  readonly customerId: string;
  readonly customerEmail: string;
  /** Integer, minor units (cents). */
  readonly amountCents: number;
  /** ISO-4217 code. */
  readonly currency: string;
}

const CONTRACT = "OrderPlaced";

/**
 * Validates an untrusted event and returns the fields billing needs.
 * Every problem is reported at once; any problem throws `ContractViolationError`.
 */
export function decodeOrderPlaced(raw: unknown): OrderPlacedEvent {
  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
    throw new ContractViolationError(CONTRACT, ["event must be a JSON object"]);
  }
  const event = raw as Record<string, unknown>;
  const issues: string[] = [];

  if (event.type !== "OrderPlaced") {
    issues.push(`type: expected "OrderPlaced", got ${describe(event.type)}`);
  }
  const orderId = requireString(event, "orderId", issues);
  const customerId = requireString(event, "customerId", issues);
  const customerEmail = requireString(event, "customerEmail", issues);
  if (customerEmail !== "" && !customerEmail.includes("@")) {
    issues.push("customerEmail: expected an email address");
  }

  const amountCents = event.amountCents;
  if (!isMinorUnits(amountCents)) {
    issues.push(`amountCents: expected an integer number of cents, got ${describe(amountCents)}`);
  }
  const currency = event.currency;
  if (!isCurrencyCode(currency)) {
    issues.push(`currency: expected an ISO-4217 code, got ${describe(currency)}`);
  }

  if (issues.length > 0 || !isMinorUnits(amountCents) || !isCurrencyCode(currency)) {
    throw new ContractViolationError(CONTRACT, issues);
  }
  return { orderId, customerId, customerEmail, amountCents, currency };
}

function requireString(event: Record<string, unknown>, key: string, issues: string[]): string {
  const value = event[key];
  if (typeof value !== "string" || value.trim() === "") {
    issues.push(`${key}: expected a non-empty string, got ${describe(value)}`);
    return "";
  }
  return value;
}

function describe(value: unknown): string {
  if (value === undefined) {
    return "missing";
  }
  if (value === null) {
    return "null";
  }
  return `${typeof value} ${JSON.stringify(value)}`;
}
